#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Staging baseline cutover: reconcile schema, repair migration history, dry-run push.
# Run from the repo root:  bash schema/staging-baseline-wizard.sh
# Rehearse on a duplicate of Staging first, then run it again against Staging itself.
# Never against Production: the reconcile is Staging-only and this wizard refuses the prod ref.

TOTAL_STAGES=9

ENV_FILE=/dev/null   # never persist the DB URL anywhere
STAGING_REF="mzjsuvatrzhciojmbbbm"
PROD_REF="zvoijyneresvkadpprel"
RECONCILE="supabase/reconcile/20261009_staging_reconcile.sql"
NEW_VERSIONS=(20261009000000 20261009000100)
EXPECTED_PENDING="20261013120000"
SNAPSHOT_SCHEMA="schema/staging-schema.sql"
SNAPSHOT_MAX_VERSION="20261014190000"

[[ -f "$RECONCILE" && -d supabase/migrations ]] || { echo "Run this from the aios repo root."; exit 1; }
command -v psql >/dev/null || { echo "psql is required."; exit 1; }

LOG_DIR="schema/wizard-logs/$(date +%Y%m%d-%H%M%S)"
mkdir -p "$LOG_DIR"

# sql "query" runs one read query against the target, unaligned output.
sql() { psql "$DB_URL" -v ON_ERROR_STOP=1 -X -At -c "$1"; }

# run LOGNAME cmd...: show the command (URL masked), run it, tee output to the log.
run() {
  local log="$LOG_DIR/$1"; shift
  local shown="$*"; shown="${shown//"$DB_URL"/\$DB_URL}"
  note "\$ ${shown:0:200}"
  set +e
  "$@" 2>&1 | tee "$log"
  local rc=${PIPESTATUS[0]}
  set -e
  return "$rc"
}

abort() { printf '\n  %s✗ %s%s\n  Logs: %s\n' "$RED" "$1" "$RESET" "$LOG_DIR"; exit 1; }

banner "AIOS Staging baseline: reconcile + history repair"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Pick the target and connect"
say "Which database is this run for?"
step "copy    = the duplicate of Staging (rehearsal, do this first)"
step "staging = the real Staging project ($STAGING_REF)"
ask MODE "Type copy or staging:"
case "$MODE" in
  copy)    ask TARGET_REF "Project ref of the duplicate (the xxxx in xxxx.supabase.co):" ;;
  staging) TARGET_REF="$STAGING_REF"; say "Target ref: $TARGET_REF" ;;
  *) abort "Expected 'copy' or 'staging'." ;;
esac
[[ -n "$TARGET_REF" ]] || abort "No project ref given."
[[ "$TARGET_REF" != "$PROD_REF" ]] || abort "That is the PRODUCTION ref. This wizard never runs on Production."
[[ "$MODE" == staging || "$TARGET_REF" != "$STAGING_REF" ]] || abort "You chose 'copy' but gave the real Staging ref."

open_url "https://supabase.com/dashboard/project/$TARGET_REF/settings/database"
step "Click Connect (top bar) → Session pooler (port 5432) → copy the URI."
step "Replace [YOUR-PASSWORD] with the database password. Do NOT use the transaction pooler (6543)."
ask_secret DB_URL "Paste the connection URI (hidden):"
[[ -n "$DB_URL" ]] || abort "No URI given."
[[ "$DB_URL" == *"$TARGET_REF"* ]] || abort "The URI does not mention $TARGET_REF. Wrong project?"
[[ "$DB_URL" != *"$PROD_REF"* ]] || abort "The URI points at PRODUCTION. Stopping."
[[ "$DB_URL" != *":6543"* ]] || abort "That is the transaction pooler (6543). Use the session pooler (5432)."

sql "select 1" >/dev/null || abort "Could not connect."
[[ "$(sql "select to_regclass('environment_sync.safety') is not null")" == t ]] \
  || abort "environment_sync.safety is missing: this is not Staging or a copy of it."
say "Connected. Migration history rows: $(sql 'select count(*) from supabase_migrations.schema_migrations')"
say "Latest applied version:            $(sql 'select max(version) from supabase_migrations.schema_migrations')"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Cron jobs"
sql "select jobid, jobname, schedule, active from cron.job order by jobid" | tee "$LOG_DIR/cron-before.txt" | sed 's/^/    /'
if [[ "$MODE" == copy ]]; then
  warn "The copy's cron jobs call Staging's edge functions (hardcoded URL), which can send real WhatsApp/email."
  say "They must be unscheduled on the copy before anything else."
  confirm "Unschedule ALL cron jobs on the copy ($TARGET_REF)?" || abort "Not safe to continue with live crons on the copy."
  run cron-unschedule.txt psql "$DB_URL" -v ON_ERROR_STOP=1 -X -At -c "select cron.unschedule(jobid) from cron.job" \
    || abort "Unschedule failed."
  say "Jobs left: $(sql 'select count(*) from cron.job')"
else
  note "Staging: crons are left as they are; the reconcile does not touch them."
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Has the schema changed since the snapshot?"
say "The reconcile was generated from $SNAPSHOT_SCHEMA. Checking the target still matches it."
NEWER=$(sql "select string_agg(version, ' ' order by version) from supabase_migrations.schema_migrations where version > '$SNAPSHOT_MAX_VERSION'")
if [[ -n "$NEWER" ]]; then
  warn "Migrations applied after the snapshot: $NEWER"
else
  say "✓ No migrations applied after $SNAPSHOT_MAX_VERSION."
fi
note "Dumping the current schema (needs Docker running)..."
run schema-dump.txt npx supabase db dump --db-url "$DB_URL" -f "$LOG_DIR/current-schema.sql" \
  || abort "Schema dump failed (is Docker running?)."
if diff -u "$SNAPSHOT_SCHEMA" "$LOG_DIR/current-schema.sql" > "$LOG_DIR/schema.diff"; then
  say "✓ Schema identical to the snapshot."
else
  warn "Schema differs from the snapshot: $(grep -cE '^[+-][^+-]' "$LOG_DIR/schema.diff") changed lines."
  note "Diff saved to $LOG_DIR/schema.diff. Send it to Claude before going further:"
  note "real changes mean the reconcile must be regenerated."
  confirm "Continue anyway (only if you're sure the diff is harmless)?" || abort "Stopped at the schema check."
fi
[[ -z "$NEWER" ]] || confirm "Continue despite newer migrations?" || abort "Stopped at the schema check."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Run the reconcile"
say "Runs $RECONCILE as one transaction: any error rolls everything back."
say "It keeps all rows; it drops Staging-only objects and converts column types."
confirm "Run the reconcile on $MODE ($TARGET_REF)?" || abort "Reconcile not run."
run reconcile.txt psql "$DB_URL" -v ON_ERROR_STOP=1 -X -c "set statement_timeout = 0" -f "$RECONCILE" \
  || abort "Reconcile failed and was rolled back. Send $LOG_DIR/reconcile.txt to Claude."
say "✓ Reconcile committed."
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Collect the old migration versions"
sql "select version from supabase_migrations.schema_migrations order by 1" | LC_ALL=C sort > "$LOG_DIR/remote-versions.txt"
ls supabase/migrations | grep -oE "^[0-9]{14}" | LC_ALL=C sort -u  > "$LOG_DIR/local-versions.txt"
comm -23 "$LOG_DIR/remote-versions.txt" "$LOG_DIR/local-versions.txt" > "$LOG_DIR/old-versions.txt"
OLD_COUNT=$(wc -l < "$LOG_DIR/old-versions.txt" | tr -d ' ')
say "Remote-only versions to mark reverted: $OLD_COUNT (expect about 778)"
say "First: $(head -1 "$LOG_DIR/old-versions.txt")   Last: $(tail -1 "$LOG_DIR/old-versions.txt")"
for v in "${NEW_VERSIONS[@]}" "$EXPECTED_PENDING"; do
  ! grep -qx "$v" "$LOG_DIR/old-versions.txt" || abort "$v is in the revert list. Something is off."
done
(( OLD_COUNT > 0 )) || abort "Nothing to revert. Was the history already repaired?"
confirm "Does the count look right?" || abort "Stopped before touching the history."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Mark the old versions reverted"
say "Removes $OLD_COUNT rows from supabase_migrations.schema_migrations. Schema and data are untouched."
confirm "Mark $OLD_COUNT versions reverted on $MODE ($TARGET_REF)?" || abort "History not repaired."
# shellcheck disable=SC2046
run repair-reverted.txt npx supabase migration repair --db-url "$DB_URL" --status reverted \
  $(cat "$LOG_DIR/old-versions.txt") || abort "Repair (reverted) failed."
say "Rows left in history: $(sql 'select count(*) from supabase_migrations.schema_migrations')"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Mark the baseline and catch-up applied"
say "Records ${NEW_VERSIONS[*]} as applied (the reconcile already made the schema match them)."
confirm "Mark ${NEW_VERSIONS[*]} applied?" || abort "Stopped before marking the new versions."
run repair-applied.txt npx supabase migration repair --db-url "$DB_URL" --status applied "${NEW_VERSIONS[@]}" \
  || abort "Repair (applied) failed."
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Dry-run push"
say "Expect exactly one pending migration: $EXPECTED_PENDING (Carmen persona)."
run push-dry-run.txt npx supabase db push --db-url "$DB_URL" --dry-run || warn "Dry run exited non-zero."
run migration-list.txt npx supabase migration list --db-url "$DB_URL" || true
PENDING=$(grep -oE '[0-9]{14}' "$LOG_DIR/push-dry-run.txt" | sort -u | tr '\n' ' ')
if [[ "$PENDING" == "$EXPECTED_PENDING " ]]; then
  say "✓ Only $EXPECTED_PENDING is pending."
else
  warn "Pending versions: ${PENDING:-none}. Expected only $EXPECTED_PENDING. Send the logs to Claude."
fi
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Smoke check"
say "environment_sync tables (rows):"
sql "select relname || ': ' || n_live_tup from pg_stat_user_tables where schemaname = 'environment_sync' order by 1" \
  | tee "$LOG_DIR/environment-sync.txt" | sed 's/^/    /'
say "Public tables: $(sql "select count(*) from pg_tables where schemaname = 'public'")"
say "Rows in leads / clients: $(sql 'select (select count(*) from public.leads) || $$ / $$ || (select count(*) from public.clients)')"
if [[ "$MODE" == copy ]]; then
  step "Now poke at the copy in the dashboard (Table Editor, a few RLS-protected tables)."
  open_url "https://supabase.com/dashboard/project/$TARGET_REF/editor"
else
  step "Open the develop Preview/Staging app, log in, and click through leads, clients and Carmen."
fi
pause "Done looking? Press Enter"

finish
say "Logs: $LOG_DIR  (share push-dry-run.txt and reconcile.txt with Claude)"
